'use strict';
const assert=require('node:assert/strict');
const fs=require('node:fs');
const path=require('node:path');
const root=path.resolve(__dirname,'../..');
const read=f=>fs.readFileSync(path.join(root,f),'utf8');
const mapper=read('docs/scifi-ui/scripts/formatx-apex-scene-stability.js');
const material=read('docs/scifi-ui/scripts/formatx-core-mesh3d-material-v20.js');
const shape=read('docs/scifi-ui/scripts/formatx-core-shape-v14.js');
const geometry=read('docs/scifi-ui/scripts/formatx-core-geometry-v13.js');
const mesh=read('docs/scifi-ui/scripts/formatx-core-mesh3d-v11.js');
const fracture=read('docs/scifi-ui/scripts/formatx-core-fracture3d-v11.js');
const grade=read('docs/scifi-ui/styles/formatx-core-cinematic-grade-v20.css');
const kick=read('docs/scifi-ui/scripts/formatx-core-cinematic-kick-v11.js');
const infinite=read('docs/scifi-ui/scripts/formatx-infinite-scroll.js');

assert.match(mapper,/fxApexSceneStability==='ready-v30'/,'v20 mapper revision missing');
assert.match(mapper,/formatx-core-mesh3d-material-v20\.js\?v=20260809-distributed-hdr-facets-v20/,'v20 material bootstrap missing');
assert.match(mapper,/formatx-core-cinematic-grade-v20\.css\?v=20260809-distributed-hdr-v20/,'v20 grade bootstrap missing');
assert.match(mapper,/reference-glass-v20-distributed-high-dynamic-facets/,'v20 material contract missing');
assert.match(mapper,/reference-polygon-contrast-v20/,'v20 calibration contract missing');
assert.match(mapper,/cinematic-distributed-hdr-reference-glass-v30/,'v20 visual marker missing');
assert.doesNotMatch(mapper,/scrollTo\s*\(|scrollIntoView\s*\(|preventDefault\s*\(/,'mapper must not capture scrolling');

assert.match(material,/vec2 cp=vec2\(vP\.x,vP\.y-\.18\)/,'object-space center correction missing');
assert.match(material,/float f1=sat\(dot\(fn,L1\)\),f2=sat\(dot\(fn,L2\)\),f3=sat\(dot\(fn,L3\)\),f4=sat\(dot\(fn,L4\)\)/,'multi-direction flat-facet lighting missing');
assert.match(material,/float planeGlow=sm\(\.34,\.72,face\)/,'distributed facet shoulder missing');
assert.match(material,/float planePeak=pow\(face,6\.0\)/,'facet peak missing');
assert.match(material,/float webA=.*5\.2/s,'widened webA missing');
assert.match(material,/float webB=.*5\.8/s,'widened webB missing');
assert.match(material,/float webC=.*6\.4/s,'widened webC missing');
assert.match(material,/float hAxis=exp\(-abs\(cp\.y\)\*11\.0\)/,'horizontal object-space energy axis missing');
assert.match(material,/float ridgeA=/,'diagonal ridge A missing');
assert.match(material,/float ringGlow=/,'surface ring glow missing');
assert.match(material,/float highlight=sat\(/,'distributed highlight coverage mask missing');
assert.match(material,/layerWeight\*\(\.24\*planeGlow\+\.18\*web/,'highlight-dependent alpha coverage missing');
assert.match(material,/fxCoreHighlightModel='distributed-high-dynamic-facets-v20'/,'v20 highlight model marker missing');
assert.match(material,/fxCoreHighlightCoverage='facet-web-axis-ring-distribution-v20'/,'v20 highlight coverage marker missing');
assert.match(material,/fxCoreMeshMaterial='reference-glass-v20'/,'v20 material applied marker missing');
assert.match(material,/fxCoreMeshMaterialPatch='applied-v20'/,'v20 material patch marker missing');
assert.match(material,/fxCoreMaterialCenter='object-space-y-minus-0\.18'/,'material center marker missing');
assert.doesNotMatch(material,/drawImage\s*\(|new Image\s*\(|background-image/i,'MAG material must remain procedural');

assert.match(shape,/aPosition\.y\*\.72/,'reference Y ratio missing');
assert.match(shape,/fxCoreShapeMesh='applied-v14'/,'mesh shape patch missing');
assert.match(shape,/fxCoreShapeFracture='applied-v14'/,'fracture shape patch missing');
assert.match(geometry,/value\*1\.15/,'true 3D scale multiplier missing');
assert.match(geometry,/fxCoreGeometryScale='1\.15x-true-3d-uniform'/,'true 3D scale marker missing');
assert.match(mesh,/getContext\('webgl2'/,'WebGL2 mesh context missing');
assert.match(mesh,/gl\.enable\(gl\.DEPTH_TEST\)/,'depth testing missing');
assert.match(mesh,/gl\.drawElements\(gl\.TRIANGLES/,'indexed triangles missing');
assert.match(mesh,/fxCoreGeometry='indexed-triangle-mesh-v11'/,'indexed mesh marker missing');
assert.match(fracture,/gl\.drawElements\(gl\.LINES/,'indexed fracture lines missing');
assert.match(fracture,/fxCoreFracture3d='ready-v11'/,'fracture marker missing');

assert.match(grade,/brightness\(2\.00\)/,'desktop brightness calibration missing');
assert.match(grade,/opacity: 0\.84/,'desktop fracture strength missing');
assert.match(grade,/brightness\(2\.06\)/,'mobile brightness calibration missing');
assert.match(grade,/opacity: 0\.82/,'mobile fracture strength missing');
assert.match(grade,/brightness\(1\.68\)/,'mobile fracture brightness missing');

assert.match(kick,/formatx:organismresponse.*\.74,1\.15,2100/s,'frame-rate independent response impulse missing');
assert.match(infinite,/const VERSION = 'seamless-v7'/,'seamless-v7 regressed');
assert.match(infinite,/root\.dataset\.fxInfiniteInput = 'native'/,'native momentum regressed');
console.log('PASS: v20 preserves real centered indexed WebGL2 geometry while distributing HDR facet, web, axis and ring highlights without changing seamless-v7 native scrolling.');
